#!/usr/bin/env python3
"""Build the PIREVO zero-cost, original-editorial product comparator.
Contains NO remote images, Amazon ratings, live pricing, or unverified referral claims.
Safe to regenerate following the normal PIREVO catalog generator.
"""
from pathlib import Path
import subprocess,json,html,xml.etree.ElementTree as ET
R=Path(__file__).resolve().parent.parent
B=R/"public/pirevo"
js='const fs=require("fs"),vm=require("vm"),w={};vm.runInNewContext(fs.readFileSync("public/pirevo/store-data.js","utf8"),{window:w});process.stdout.write(JSON.stringify(w.PIREVO_STORE))'
store=json.loads(subprocess.check_output(["node","-e",js],cwd=R,text=True))
source=store["products"]; collections=store["collections"]
safe=lambda s:html.escape(str(s or ""),quote=True)
assert len(source)==138
items=[]
for p in source:
 items.append({"slug":p["slug"],"name":p["shortName"],"fullName":p["fullName"],"brand":p["brand"],"category":p["collection"],"bestFor":p.get("bestFor") or "Compare the exact product model before purchasing.","caveat":p.get("caveat") or "Verify product dimensions, materials, seller and retailer terms.","page":"/pirevo/products/"+p["slug"]+"/index.html","verifiedUS": p["slug"] in ["apple-airtag-2","levoit-core-200s","govee-table-lamp-2","cosrx-snail-mucin-96","aeropress-original-b0047"]})
for p in items:
 assert (B/p["page"].removeprefix("/pirevo/")).is_file(),p["slug"]
(B/"compare-data.json").write_text(json.dumps({"version":"2026-10-22","method":"Existing PIREVO editorial records. No live prices, reviews, seller, rank, hands-on testing or regional availability claims.","items":items},separators=(",",":"),ensure_ascii=False)+"\n")
presets=[
 ("Small-space kitchen helpers","churboro-spice-jars-25","oxo-pop-5pc","rubbermaid-brilliance-5"),
 ("Weeknight cooking equipment","crockpot-design-7qt","ninja-possiblecooker-pro-plus","crockpot-manual-7qt"),
 ("Travel-ready charging","ugreen-nexode-pro-65w","tessan-europe-adapter-2","superdanny-10ft-power-strip"),
 ("Small-space organization","vtopmart-drawer-organizers-25","vtopmart-under-sink-drawers-4","amazon-basics-storage-cubes-6"),
 ("Smart home and everyday tech","apple-airtag-2","echo-dot-charcoal","amazon-smart-plug-2")
]
slugs={p["slug"] for p in items}
for p in presets:assert all(x in slugs for x in p[1:]),p
P=B/"compare";P.mkdir(exist_ok=True)
head="""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Compare Products Side by Side | PIREVO Buying Desk</title>
<meta name="description" content="Compare up to three PIREVO products by use case, fit and buying tradeoffs, with 138 catalog choices. Independent editorial comparisons without live Amazon prices or copied reviews.">
<meta name="robots" content="index,follow,max-image-preview:large">
<link rel="canonical" href="https://www.astralabsph.com/pirevo/compare/">
<link rel="icon" type="image/svg+xml" href="/pirevo/favicon.svg">
<meta property="og:type" content="website"><meta property="og:title" content="PIREVO Buying Desk | Compare Curated Product Finds">
<meta property="og:description" content="Choose up to three products to compare actual fit, practical tradeoffs and the details to verify before checkout.">
<link rel="stylesheet" href="/pirevo/compare/style.css"></head>"""
intro="""<body><header class="top"><a href="/pirevo/" class="brand" aria-label="PIREVO home">PIREVO<span class="brand-dot">.</span></a><nav aria-label="Navigation"><a href="/pirevo/catalog/">All products</a><a href="/pirevo/guides/">Buying guides</a><a href="/pirevo/international/">Global shopping</a></nav></header>
<main><div class="crumb"><a href="/pirevo/">Home</a><span>/</span><a href="/pirevo/catalog/">Catalog</a><span>/</span>Buying Desk</div>
<section class="hero"><div class="eyebrow">PIREVO / THE BUYING DESK</div><h1>Compare before you commit.</h1><p>Choose up to three products. Compare who they suit, the tradeoffs to consider, and the details worth double-checking at checkout. No borrowed ratings, fictional price cuts, or sales pressure.</p>
<div class="trust"><span>138 catalog candidates</span><span>Independent editorial notes</span><span>Amazon handles checkout</span></div></section>
<section class="workbench" aria-labelledby="build-title"><div class="heading"><div><span class="eyebrow">01 · Build your comparison</span><h2 id="build-title">Your shortlist</h2></div><button type="button" class="reset" id="reset">Clear selections</button></div>
<div class="choices"><label>Filter by category<select id="category" aria-label="Filter product choices by category"><option value="">All categories</option>"""
cats="".join('<option value="'+safe(c["id"])+'">'+safe(c["name"])+"</option>" for c in collections)
inputs="""</select></label><label>Search products<input id="find" type="search" placeholder="e.g. air purifier, 7-qt, travel" autocomplete="off" aria-label="Search product names and brands"></label></div>
<div class="product-picks" role="group" aria-label="Choose up to three products">
<label><span>PRODUCT 01</span><select id="choice1" aria-label="First product"><option value="">Select first product</option></select></label>
<label><span>PRODUCT 02</span><select id="choice2" aria-label="Second product"><option value="">Select second product</option></select></label>
<label><span>PRODUCT 03</span><select id="choice3" aria-label="Third product"><option value="">Select third product (optional)</option></select></label></div>
<div class="actions"><span id="status" role="status" aria-live="polite">Choose at least two different products to compare.</span><button type="button" class="copy" id="copy" disabled>Copy comparison link</button></div>
</section>
<section class="comparison" id="results" aria-live="polite" aria-labelledby="comparison-title" hidden><div class="heading"><div><span class="eyebrow">02 · Evidence-based shortlisting</span><h2 id="comparison-title">Side-by-side buying notes</h2></div></div>
<p class="caption">Descriptions summarize existing PIREVO editorial research. They are not third-party customer reviews or verified lab tests, and may not be suitable for every shopper.</p><div id="matrix" class="matrix-wrap"></div>
<div class="buying-guard"><strong>Before ordering</strong><p>Open the individual buying notes, then review the exact Amazon listing for model, seller, dimensions, shipping location, price, taxes, returns and warranty. Country-specific product matches may differ. OneLink earnings settings do not guarantee local stock or commission attribution on a particular item.</p></div></section>
<section class="presets" aria-labelledby="preset-title"><div class="eyebrow">Start with a buying decision</div><h2 id="preset-title">Comparisons worth exploring</h2><div class="presets-grid">"""
cards="".join('<a class="preset" href="?p='+",".join(safe(x) for x in p[1:])+'"><small>COMPARE 3 FINDS</small><strong>'+safe(p[0])+'</strong><span>Open side-by-side →</span></a>' for p in presets)
end="""</div></section><section class="about"><span class="eyebrow">Our method</span><h2>The difference is in the questions.</h2><p>We compare practicality and tradeoffs instead of guessing who “wins.” A product can fit one person’s space, budget and routine while being a poor choice for another. Our source records have not been independently rechecked for every specification or country, so we explicitly send shoppers to the original retailer for current details.</p><div class="about-links"><a href="/pirevo/editorial-policy.html">Read editorial standards →</a><a href="/pirevo/international/">International shopping rules →</a></div></section></main>
<footer><strong>PIREVO</strong><span>Independent affiliate product discovery. As an Amazon Associate I earn from qualifying purchases.</span><a href="/pirevo/affiliate-disclosure.html">Affiliate disclosure</a></footer>
<script src="/pirevo/config.js" defer></script><script src="/pirevo/business-analytics.js" defer></script><script src="/pirevo/compare/app.js" defer></script></body></html>"""
(P/"index.html").write_text(head+intro+cats+inputs+cards+end)
CSS="""@import url('');:root{color-scheme:light;--ink:#152d24;--muted:#637568;--green:#204b37;--line:#d6e3d6;--paper:#f4f6ef;--cream:#fffcf5;font:16px/1.55 Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink)}a{color:inherit}a:focus-visible,button:focus-visible,select:focus-visible,input:focus-visible{outline:3px solid #6fb18b;outline-offset:3px}.top{padding:18px max(20px,calc((100vw - 1160px)/2));background:#19392d;color:white;display:flex;gap:22px;align-items:center;justify-content:space-between;flex-wrap:wrap}.top a{text-decoration:none}.brand{font-weight:950;font-size:25px;letter-spacing:.13em}.brand-dot{color:#bdde88}.top nav{display:flex;gap:20px;flex-wrap:wrap;font-size:13px}.top nav a{color:#f5f8f3}main{max-width:1170px;margin:auto;padding:29px 22px 80px}.crumb{display:flex;gap:10px;align-items:center;font-size:12px;color:#697b6e}.crumb a{text-decoration:none}.eyebrow{font-size:11px;font-weight:850;letter-spacing:.17em;color:#4d8065}.hero{padding:56px 0 48px;border-bottom:1px solid var(--line)}h1{font:500 clamp(42px,6.2vw,78px)/1.02 Georgia,serif;letter-spacing:-.056em;margin:13px 0 23px;max-width:850px}.hero>p{font-size:18px;line-height:1.75;max-width:820px;color:#4c6153}.trust{display:flex;flex-wrap:wrap;gap:9px;margin-top:25px}.trust span{background:#e4eee2;border:1px solid #d3dfcf;border-radius:100px;padding:8px 14px;font-size:11px;font-weight:800}.workbench,.comparison{padding:32px;background:var(--cream);border:1px solid var(--line);border-radius:22px;margin-top:30px}.heading{display:flex;align-items:end;justify-content:space-between;gap:20px;flex-wrap:wrap}h2{font:500 clamp(26px,3.4vw,40px)/1.12 Georgia,serif;letter-spacing:-.035em;margin:9px 0 13px}.choices{display:grid;grid-template-columns:1fr 1fr;gap:15px;margin:19px 0 16px}label{display:block;font-size:12px;font-weight:800;color:#55705b}label select,label input{display:block;width:100%;height:46px;margin-top:7px;padding:10px 13px;background:white;border:1px solid #c4d4c6;border-radius:11px;color:#203a2e;font:500 14px system-ui;min-width:0}.product-picks{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px}.product-picks label{padding:16px;border:1px solid #e3e8dc;border-radius:14px;background:#eff3ec}.actions{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap;padding-top:21px}.actions span{color:#5e7564;font-size:12px}.reset,.copy{border:1px solid #acc4b2;border-radius:10px;padding:10px 15px;background:white;color:#234330;font:750 12px system-ui;cursor:pointer}.copy{background:#19392d;color:white;border-color:#19392d}.copy:disabled{opacity:.45;cursor:not-allowed}.caption{font-size:13px;color:#607365}.matrix-wrap{overflow-x:auto;border-radius:15px;border:1px solid var(--line);background:white;margin:20px 0}.matrix{width:100%;border-collapse:collapse;min-width:630px;table-layout:fixed}.matrix th,.matrix td{border-bottom:1px solid #e1eae0;text-align:left;padding:17px 19px;vertical-align:top;overflow-wrap:anywhere}.matrix thead th{background:#eff5ec;color:#264a36}.matrix th:first-child,.matrix td:first-child{width:18%;background:#f6f7f2;font-size:12px;text-transform:uppercase;letter-spacing:.08em;font-weight:850;color:#58705e}.matrix thead th:first-child{background:#e8f0e7}.matrix td{font-size:14px;line-height:1.65}.matrix td a{font-weight:850;color:#245b40}.matrix tbody tr:last-child td{border-bottom:none}.buying-guard,.about{background:#e5eee3;padding:27px;border-radius:17px;margin-top:22px;color:#335340}.buying-guard p,.about p{line-height:1.8;font-size:14px}.presets{padding:55px 0 30px}.presets-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}.preset{display:flex;flex-direction:column;justify-content:space-between;min-height:170px;padding:24px;background:white;border:1px solid var(--line);border-radius:16px;text-decoration:none}.preset small{color:#698a73;font-size:10px;letter-spacing:.13em;font-weight:850}.preset strong{font:500 25px/1.15 Georgia,serif;margin:10px 0}.preset span{font-size:12px;color:#236041;font-weight:800}.preset:hover{border-color:#79a98a;background:#f8fff6}.about-links{display:flex;gap:20px;flex-wrap:wrap;font-weight:800;font-size:13px}.about{margin-top:25px}footer{padding:35px max(20px,calc((100vw - 1160px)/2));background:#19392d;color:white;display:flex;gap:25px;flex-wrap:wrap;justify-content:space-between;font-size:12px}footer a{color:white}@media(max-width:800px){.product-picks,.presets-grid{grid-template-columns:1fr 1fr}.choices{grid-template-columns:1fr}.workbench,.comparison{padding:20px}}@media(max-width:570px){main{padding:21px 13px 55px}.product-picks,.presets-grid{grid-template-columns:1fr}.hero{padding:39px 0 30px}.workbench,.comparison{margin-top:20px}.matrix th,.matrix td{padding:13px}.top nav{gap:12px}}"""
