js_app="""(function(){"use strict";const $=x=>document.getElementById(x),sel=[$("choice1"),$("choice2"),$("choice3")],category=$("category"),find=$("find"),reset=$("reset"),copy=$("copy"),status=$("status"),results=$("results"),matrix=$("matrix");let items=[],bySlug=new Map(),chosen=[];const max=3;const txt=(tag,text,cls)=>{const x=document.createElement(tag);x.textContent=text;if(cls)x.className=cls;return x};function cleanSlug(x){return /^[a-z0-9-]+$/.test(x)?x:null};function parse(){let v=new URLSearchParams(location.search).get("p")||"";return [...new Set(v.split(",").slice(0,3).map(cleanSlug).filter(Boolean))]};function setUrl(){const u=new URL(location.href);if(chosen.length)u.searchParams.set("p",chosen.join(","));else u.searchParams.delete("p");history.replaceState(null,"",u.pathname+u.search+u.hash)}function opts(){const term=find.value.trim().toLowerCase(),cat=category.value;const filtered=items.filter(p=>(!cat||p.category===cat)&&(!term||(p.name+" "+p.fullName+" "+p.brand+" "+p.bestFor).toLowerCase().includes(term)));sel.forEach((el,i)=>{const current=chosen[i]||"";el.textContent="";const first=document.createElement("option");first.value="";first.textContent=i===2?"Optional third product":"Choose product "+(i+1);el.append(first);const allowed=new Set(filtered.map(p=>p.slug));if(current)allowed.add(current);items.filter(p=>allowed.has(p.slug)).sort((a,b)=>a.name.localeCompare(b.name)).forEach(p=>{const opt=document.createElement("option");opt.value=p.slug;opt.textContent=p.brand+" · "+p.name;el.append(opt)});el.value=current;});}function cell(row,text){row.append(txt("td",text))}function render(){const entries=chosen.map(k=>bySlug.get(k)).filter(Boolean);copy.disabled=entries.length<2;results.hidden=entries.length<2;status.textContent=entries.length<2?"Select two different items to compare.":entries.length+" products selected. Comparison is editorial, not a live price or stock feed.";matrix.textContent="";if(entries.length<2)return;const t=document.createElement("table");t.className="matrix";const hd=t.createTHead().insertRow();hd.append(txt("th","Consideration"));entries.forEach(p=>hd.append(txt("th",p.brand+" · "+p.name)));const body=t.createTBody();for(const [name,fn] of [["Best suited for",p=>p.bestFor],["Tradeoff to consider",p=>p.caveat],["Model verification",p=>p.verifiedUS?"US product identity previously checked; verify current details":"Not independently verified across all regions"],["Country availability",p=>"Unknown for your delivery location. Confirm on the retailer page."]]){const row=body.insertRow();row.append(txt("td",name));entries.forEach(p=>cell(row,fn(p)))}const row=body.insertRow();row.append(txt("td","Next step"));entries.forEach(p=>{const td=document.createElement("td"),a=document.createElement("a");a.href=p.page;a.textContent="Open PIREVO buying notes →";td.append(a);row.append(td)});matrix.append(t)}function change(index,v){if(v&&chosen.includes(v)&&chosen[index]!==v){status.textContent="That product is already in the comparison. Choose a different one.";opts();return;}chosen[index]=v;chosen=chosen.filter(Boolean);opts();setUrl();render();if(chosen.length>=2&&window.PIREVO_ANALYTICS){window.PIREVO_ANALYTICS.event("compare_view",{item_name:chosen.join(","),link_text:"shopper_selected_"+chosen.length+"_products"})}}function activate(slugs){chosen=[...new Set(slugs.filter(x=>bySlug.has(x)))].slice(0,3);opts();setUrl();render()}sel.forEach((x,i)=>x.addEventListener("change",()=>change(i,x.value)));category.addEventListener("change",opts);find.addEventListener("input",opts);reset.addEventListener("click",()=>{category.value="";find.value="";activate([])});copy.addEventListener("click",async()=>{const url=location.href;try{await navigator.clipboard.writeText(url);copy.textContent="Link copied";setTimeout(()=>copy.textContent="Copy comparison link",1700)}catch(e){const input=document.createElement("textarea");input.value=url;document.body.append(input);input.select();const ok=document.execCommand("copy");input.remove();copy.textContent=ok?"Link copied":"Copy URL from address bar";setTimeout(()=>copy.textContent="Copy comparison link",2000)}});fetch("/pirevo/compare-data.json",{credentials:"omit"}).then(r=>{if(!r.ok)throw Error("No catalog");return r.json()}).then(data=>{items=data.items||[];bySlug=new Map(items.map(p=>[p.slug,p]));activate(parse())}).catch(()=>{status.textContent="Product data is temporarily unavailable. Please browse the regular catalog.";copy.disabled=true})})();"""
(P/"app.js").write_text(js_app+"\n")
for sitemap in [R/"public/sitemap.xml",B/"sitemap.xml"]:
 s=sitemap.read_text();loc="https://www.astralabsph.com/pirevo/compare/"
 if "<loc>"+loc+"</loc>" not in s:s=s.replace("</urlset>",'<url><loc>'+loc+'</loc><lastmod>2026-10-22</lastmod></url>\n</urlset>')
 sitemap.write_text(s)
print(json.dumps({"comparison_candidates":len(items),"preset_groups":len(presets),"url":"/pirevo/compare/","no_product_images":True},indent=2))
